insert into public.traditions (slug, name, also_called, summary, origin, early_church, stance_heading, stance, sort_order, reviewed_on) values
  ('halloween', 'Halloween', null, 'A night of costumes and candy that grew out of the Christian eve of All Saints, carrying Irish and Scottish folk customs whose older roots historians still debate.', 'Halloween is a contraction of “All Hallows’ Eve,” the night before All Saints’ Day (All Hallows) on November 1. Christians had long remembered martyrs on the anniversaries of their deaths, and in 609 or 610 Pope Boniface IV dedicated Rome’s Pantheon to Mary and all the martyrs [3][8]. A feast of all saints on November 1 appears in England and the Frankish lands in the eighth and ninth centuries, and in 835 the emperor Louis the Pious, at the request of Pope Gregory IV, ordered it kept throughout his empire [1]. In the early eleventh century (traditionally dated to 998), Abbot Odilo of Cluny ordered his monasteries to commemorate all the faithful departed, a day that spread as All Souls’ Day on November 2 [7].

Samhain (Old Irish samain), the start of winter in the medieval Irish calendar, also fell at the beginning of November. Irish tales written down by Christian monks from about the tenth century set royal assemblies and encounters with the otherworld at Samhain [1][2]. Much earlier, a bronze calendar from Coligny in Gaul (2nd century AD) names a month SAMON(I), often reconstructed as Samonios, though how it relates to the Irish feast is uncertain [5].

By the early modern period, Hallowe’en in Scotland and Ireland was a night for fortune-telling, bonfires and going door to door in disguise (“guising”) [1]. Robert Burns’s poem “Halloween,” published in 1786, describes the fortune-telling charms of a Scottish country Halloween: pulling kail stalks, burning nuts, sowing hemp seed [4]. In parts of England, children and the poor went “souling” at Hallowtide, the days around All Saints, asking for soul cakes in return for prayers for the dead [1]. Irish and Scottish immigrants carried these customs to North America in the nineteenth century, where Halloween became a community and children’s holiday; the phrase “trick or treat” is first recorded in Ontario in 1917 [9].', 'Nothing like Halloween appears in the New Testament or in Christian writings before AD 100. The earliest Christians did remember their dead: the New Testament speaks of a “great cloud of witnesses” (Hebrews 12:1) and of the souls of martyrs (Revelation 6:9–11), and in the mid-second century the church at Smyrna planned to gather each year on the anniversary of Bishop Polycarp’s martyrdom [6]. A single feast for all the saints came centuries later [3].', 'Should Christians keep Halloween?', 'Halloween’s name is Christian: it is the eve of All Saints. Whether its customs go back to Samhain, historians still debate [1][2]. But as far back as its folk customs are recorded, the night has centered on the dead and on telling the future [1]. Burns’s “Halloween” is a catalog of fortune-telling charms [4], and today’s Halloween still trades in ghosts, witches and fear [10].

God told Israel, “There shall not be found among you any one that . . . useth divination, or an observer of times, or an enchanter, or a witch” (Deuteronomy 18:10). Paul wrote, “have no fellowship with the unfruitful works of darkness, but rather reprove them” (Ephesians 5:11), and “Abstain from all appearance of evil” (1 Thessalonians 5:22).

So we don’t keep Halloween, and we encourage believers to set the night aside. Paul also tells believers not to judge one another over days (Romans 14:5–6), so we offer this as a conviction to weigh, not a test of anyone’s faith.', 1, '2026-10-25'),
  ('christmas', 'Christmas', null, 'The feast of Jesus’ birth, kept on December 25 in Rome by 336. Why that date was chosen is one of the oldest debates in Christian history.', 'The Gospels of Matthew and Luke describe Jesus’ birth but give no date or season. Early Christian writers who tried to work one out disagreed: around 200, Clement of Alexandria reported calculations placing it in the spring, including on the 25th of the Egyptian month Pachon (May 20) [5].

The earliest evidence for a celebration on December 25 is a Roman list of feast days, the Depositio Martyrum, which begins: “December 25: Christ born in Bethlehem of Judea.” It survives in a collection known as the Chronography of 354 and is generally dated to 336 [3]. The same collection’s civil calendar marks December 25 as “N(atalis) Invicti,” the birthday of the Unconquered (Sun), with thirty chariot races [4].

From Rome the date spread east. In a sermon of 386, John Chrysostom told his congregation in Antioch that the feast had been kept there for less than ten years; many Eastern churches had celebrated Jesus’ birth and baptism together on January 6, as the Armenian church still does [2]. Orthodox churches that follow the Julian calendar keep December 25 on what is now January 7 in the civil calendar.

Later Christians disputed the feast as well. Puritan reformers objected that it had no warrant in Scripture; England’s Parliament abolished its observance in 1647 [9], and Massachusetts fined anyone caught keeping it from 1659 to 1681 [6]. In the United States, Christmas became a federal holiday in 1870 [10].', 'There is no record of Christians celebrating Jesus’ birth before AD 100. The New Testament centers on his death and resurrection, and Paul’s letters mention the birth only in passing (Galatians 4:4) [2]. The earliest Christian observances known are the weekly gathering on the first day of the week and the yearly Pascha, the feast of the resurrection [2].', 'Should Christians keep Christmas?', 'Scripture gives no feast of Jesus’ birth. The apostles preached his death and resurrection, Paul mentions the birth only in passing (Galatians 4:4), and for three centuries the church kept no feast of the nativity [2]. The first evidence of a feast on December 25 comes from Rome in 336, in a collection whose calendar marks the same day as the birthday of the Unconquered Sun [3][4].

God told Israel not to worship him the way the nations worshiped their gods: “enquire not after their gods, saying, How did these nations serve their gods? even so will I do likewise” (Deuteronomy 12:30). “What thing soever I command you, observe to do it: thou shalt not add thereto” (Deuteronomy 12:32). Jesus warned against “teaching for doctrines the commandments of men” (Mark 7:7).

Christians have reached this conclusion before. Puritan reformers objected that the feast had no warrant in Scripture; England’s Parliament abolished it in 1647 [9], and Massachusetts fined anyone caught keeping it from 1659 to 1681 [6].

So we don’t keep Christmas. We remember Christ’s coming every day, and keep the feast Scripture does give: “Christ our passover is sacrificed for us: Therefore let us keep the feast” (1 Corinthians 5:7–8). Paul also tells believers not to judge one another over days (Romans 14:5–6), so we offer this as a conviction to weigh, not a test of anyone’s faith.', 2, '2026-10-25'),
  ('resurrection-day', 'Resurrection Day', 'Called Easter in English', 'The yearly feast of Christ’s death and resurrection, kept since at least the second century as Pascha, Passover. Its English name, Easter, comes from an Anglo-Saxon month.', 'Christians in most languages call the feast by a form of the Greek pascha, from the Hebrew pesach, Passover: Pâques in French, Pascua in Spanish, Pasqua in Italian. Jesus was crucified at Passover, and around AD 54 Paul wrote that “Christ our passover is sacrificed for us” (1 Corinthians 5:7).

By the second century, churches disagreed about when to keep the feast. The churches of the Roman province of Asia, citing a tradition from the apostle John, kept it on the fourteenth day of the Jewish month Nisan, whatever day of the week that fell; they were later called Quartodecimans, from the Latin for “fourteenth.” Rome and most other churches kept it on a Sunday [2]. Around 155, Bishops Polycarp of Smyrna and Anicetus of Rome discussed the difference without settling it, each holding to the custom of those before him; Irenaeus later wrote that the earlier Roman bishops “neither observed it” themselves, which some historians read as meaning Rome kept no yearly Pascha before about 165 [2]. Around 190, Bishop Victor of Rome tried to cut the Asian churches off over the date [2]. A homily On Pascha by Melito of Sardis, from about 165, shows how one Quartodeciman church preached the feast, centered on Christ’s passion [7].

In 325 the Council of Nicaea agreed that all churches should keep Pascha on the same Sunday, independently of the Jewish calendar; the decision is known from Constantine’s letter to the churches [3]. It did not fix a method of calculation, disagreements persisted, and since the Gregorian calendar reform of 1582, Western and Eastern churches have usually celebrated on different dates.

The English name, Easter, has a different history. The monk Bede, writing in 725, explained that the Anglo-Saxons called April Eosturmonath after a goddess, Eostre, once honored in that month, and that the name had passed to the Christian feast [1]. Bede is the only ancient witness to this goddess [4]. The German Ostern shares the root.

Eggs and hares came later. Eggs were forbidden during the Lenten fast in medieval Europe and became part of the celebration that ended it [5], and the egg-bringing Easter hare is first described in German lands in 1682 [8].', 'The New Testament does not command a yearly feast, but it ties Jesus’ death to Passover (John 19:14; 1 Corinthians 5:7) and his resurrection to “the first day of the week” (Matthew 28:1). Talley and others take the Asian churches’ claim that their practice came from the apostle John as evidence that some yearly observance reached back near the apostolic generation, though no source from before AD 100 describes one directly [2][9].', 'Why not “Easter”?', 'The New Testament never calls this day Easter. The early church called it Pascha, Passover, because “Christ our passover is sacrificed for us” (1 Corinthians 5:7), and most of the world still does: Pascua, Pâques, Pasqua. “Easter” is an English and German name. The one time it appears in the King James Bible, Acts 12:4, it translates pascha, the word rendered “passover” everywhere else.

Bede, writing in 725, said the name came from a goddess, Eostre [1]; historians still debate that [4]. Whatever its origin, the name says nothing about what the day is for. So we call it Resurrection Day.', 3, '2026-10-25'),
  ('sunday-worship', 'Sunday Worship', null, 'Christians have gathered on the first day of the week since the New Testament era. In 321 Constantine made Sunday a civil day of rest; who changed what, and when, is still argued.', 'The Jewish Sabbath is the seventh day, Saturday, set apart in the Ten Commandments as a day of rest (Exodus 20:8–11). The New Testament records believers meeting on the first day of the week, the day of the resurrection, to break bread at Troas (Acts 20:7), and Paul told the Corinthians to set money aside on that day (1 Corinthians 16:2). Revelation 1:10 mentions “the Lord’s day.”

Writings from the next generations speak of the Sunday gathering more directly. The Didache, probably from the late first century, tells believers to gather “every Lord’s day” to break bread [2]. Around 110, Ignatius of Antioch described believers “no longer observing the Sabbath, but living in the observance of the Lord’s Day”; the Greek says literally “living according to the Lord’s,” and one manuscript reads “the Lord’s life” [3]. Around 112 the Roman governor Pliny reported that Christians met “on a fixed day” before dawn, without naming the day [4], and around 155 Justin Martyr wrote that “on the day called Sunday” Christians in town and country gathered for readings, prayer and the Eucharist, because it was the day God began creation and Christ rose [1]. The Epistle of Barnabas called it “the eighth day,” the day after the seventh [5].

In 321 the emperor Constantine ordered that courts and city workers rest on “the venerable day of the Sun,” while allowing farm work to go on [6]. Around 363 the Synod of Laodicea told Christians not to “judaize” (follow Jewish practice) by resting on the Sabbath, but to honor the Lord’s day [7]. Catholic teaching describes Sunday observance as replacing the Sabbath’s [10]. Some Christians, notably Seventh Day Baptists from the seventeenth century and Seventh-day Adventists from the nineteenth, hold that the seventh-day Sabbath remains binding [9].', 'Within the New Testament period, believers met on the first day of the week (Acts 20:7), and Revelation, usually dated to the 90s, names “the Lord’s day” (Revelation 1:10). Acts also shows Paul in synagogues on the Sabbath “as his manner was,” with Gentiles present (Acts 17:2; 13:42–44). How long and how widely Sabbath and Sunday were kept side by side is debated [8][9].', null, null, 4, '2026-10-25'),
  ('early-church-leadership', 'Early Church Leadership', null, 'How local elders and overseers became bishops and how Rome’s bishop rose to prominence, with the claim that Simon Magus founded a counterfeit church in Rome.', 'In the New Testament, local churches are led by groups of elders (presbyteroi) and overseers (episkopoi), with deacons assisting, and the two leading titles are used of the same people (Acts 20:17, 28; Titus 1:5–7). In Jerusalem, James the brother of Jesus led alongside the elders (Acts 15:13–21; 21:18), and later tradition remembered him as the city’s first bishop [4]. Timothy and Titus were sent to appoint elders in the churches (1 Timothy 3; Titus 1:5). Around 96 the letter known as 1 Clement, sent from the church in Rome to Corinth, speaks of “bishops and deacons” appointed by the apostles and their successors, and calls the same leaders presbyters [5]. The Didache likewise tells churches to “appoint for yourselves bishops and deacons” [7].

Around 110, the letters of Ignatius of Antioch show a single bishop presiding over each church in Asia Minor, with presbyters and deacons under him [6]. His letter to the Romans names no bishop there, though it greets the Roman church as the one that “presides over love” [10], and many historians conclude that Rome was led by a group of presbyters until the mid-second century [8][9].

Around 180, Irenaeus of Lyon listed the bishops of Rome from the apostles Peter and Paul through Linus to his own day, to show that the apostles’ teaching had been handed on in public, and wrote that every church should agree with Rome “on account of its preeminent authority” [2]. Second-century writers place the deaths of Peter and Paul in Rome: Dionysius of Corinth and the Roman presbyter Gaius, both quoted by Eusebius [4]. 1 Clement, written from Rome, recalls their martyrdoms [5], and Ignatius tells the Romans, “I do not, as Peter and Paul, issue commandments unto you” [10]. Around 190, Victor of Rome tried to cut off the churches of Asia over the date of Easter, and other bishops, Irenaeus among them, sharply rebuked him [12].

Simon Magus appears in Acts 8:9–24 as a Samaritan sorcerer who believed and was baptized, then offered money for the power to give the Holy Spirit; rebuked by Peter, he asked Peter to pray for him. The word simony comes from him. Second-century writers made him the father of heresy. Justin Martyr, himself from Samaria, wrote that Simon came to Rome under Claudius and was honored there as a god with a statue [3], and Irenaeus called him the one from whom “all sorts of heresies” derive [1]. Later legends, retold by Eusebius, describe Peter confronting Simon in Rome [4].', 'Between AD 30 and 100, the sources show apostles and traveling prophets, and local elders or overseers with deacons (Philippians 1:1; 1 Timothy 3:1–13; 1 Peter 5:1–4) [5][7]. No source from the period uses “bishop” for an office over more than one church, and none connects Simon Magus with any church office.', null, null, 5, '2026-10-25')
on conflict (slug) do update set name = excluded.name, also_called = excluded.also_called,
  summary = excluded.summary, origin = excluded.origin, early_church = excluded.early_church,
  stance_heading = excluded.stance_heading, stance = excluded.stance,
  sort_order = excluded.sort_order, reviewed_on = excluded.reviewed_on;

delete from public.traditions where slug not in ('halloween', 'christmas', 'resurrection-day', 'sunday-worship', 'early-church-leadership');

-- Children are replaced wholesale so removed entries disappear too.
delete from public.tradition_claims where tradition_id in (select id from public.traditions where slug in ('halloween', 'christmas', 'resurrection-day', 'sunday-worship', 'early-church-leadership'));
delete from public.tradition_timeline where tradition_id in (select id from public.traditions where slug in ('halloween', 'christmas', 'resurrection-day', 'sunday-worship', 'early-church-leadership'));
delete from public.tradition_scripture_refs where tradition_id in (select id from public.traditions where slug in ('halloween', 'christmas', 'resurrection-day', 'sunday-worship', 'early-church-leadership'));
delete from public.tradition_sources where tradition_id in (select id from public.traditions where slug in ('halloween', 'christmas', 'resurrection-day', 'sunday-worship', 'early-church-leadership'));

insert into public.tradition_claims (tradition_id, position, claim, rating, explanation)
select t.id, v.position, v.claim, v.rating, v.explanation
from (values
  ('halloween', 1, 'Halloween is the Celtic festival of Samhain under a new name.', 'debated', 'Halloween’s name and date come from the Christian feast of All Saints, but some of its customs (bonfires, divination, spirits abroad) echo what medieval Irish texts associate with Samhain [1][2]. How much of that is pre-Christian, and how much attached itself to the night later, is disputed: nearly everything known about Samhain was written down by Christians centuries after Ireland’s conversion [1].'),
  ('halloween', 2, 'The church set All Saints’ Day on November 1 to replace Samhain.', 'unverified', 'No surviving source gives that reason. The November 1 date first appears in England and the Frankish lands, and historians disagree over whether Celtic or Germanic custom shaped it [1]. The motive is undocumented.'),
  ('halloween', 3, 'Samhain was named for a Celtic lord of the dead.', 'contradicted', 'No Irish or Gaulish source names a god called Samhain; the word names a date. Its meaning is itself disputed: traditionally “summer’s end,” though some linguists connect it with a word for “assembly.” The death god first appears in eighteenth-century antiquarian speculation, not in any ancient or medieval text [1][10].'),
  ('halloween', 4, 'Trick-or-treating is an ancient pagan ritual.', 'unverified', 'Going door to door in disguise, or for soul cakes, is documented in Britain and Ireland from the early modern period, often tied to prayers for the dead [1][4]. A line from these back to pre-Christian practice is not documented, and trick-or-treating in its modern form took shape in North America in the twentieth century [2].'),
  ('christmas', 1, 'Jesus was born on December 25.', 'unverified', 'No source before about 200 gives a date, and those from around 200 disagree: Clement of Alexandria reports several [5], and a passage in Hippolytus’s Commentary on Daniel that gives December 25 is of disputed authenticity [2]. December 25 is first attested as the feast day in Rome in 336 [3].'),
  ('christmas', 2, 'December 25 was chosen to replace the Roman festival of the Unconquered Sun.', 'debated', 'Rome did celebrate the Unconquered Sun on December 25 by the mid-fourth century [4], and some later Christian writers drew the connection themselves [1]. Others argue the date came from a calculation: if Jesus was conceived on March 25, the date some early Christians assigned to his death, he was born nine months later [1][2]. The solar festival on that date is attested no earlier than the Christian one, which has led some scholars to question which came first [7].'),
  ('christmas', 3, 'Jeremiah 10 describes and condemns Christmas trees.', 'contradicted', 'Jeremiah 10:3–5 describes a tree cut from the forest, carved by a craftsman and decked with silver and gold to make an idol that cannot speak or walk. The passage is about idol-making around the sixth century BC; decorated Christmas trees are first clearly recorded in German-speaking lands in the sixteenth century, after a few ambiguous fifteenth-century mentions [8]. Some readers apply verse 2, “Learn not the way of the heathen,” as a principle against adopting pagan customs; that is an application of the passage, not what it describes.'),
  ('christmas', 4, 'Christians did not celebrate Jesus’ birth for the first three centuries.', 'supported', 'No celebration of the Nativity is recorded before the fourth century, apart from Clement of Alexandria’s report that one Egyptian group kept a festival of Jesus’ baptism [5]. Silence in the sources is not proof, but it is consistent across them [2].'),
  ('resurrection-day', 1, 'Easter is named after the Babylonian goddess Ishtar.', 'contradicted', 'The English name comes from Old English Eastre, which Bede tied to a goddess Eostre and a spring month [1]; the word shares a root with words for “east” and “dawn” [4]. Ishtar is a similar-sounding name of unrelated, Akkadian origin, and most languages call the feast Pascha, after Passover. The Ishtar link traces to Alexander Hislop’s The Two Babylons (1853; expanded 1858), which equated Easter with Astarte [6].'),
  ('resurrection-day', 2, 'Easter is named after an Anglo-Saxon goddess, Eostre.', 'debated', 'Bede is the only source, and some scholars have suspected he inferred the goddess from the month’s name. Others accept his report, and inscriptions to Germanic mother goddesses called the Austriahenae, found in 1958, may share the root [4].'),
  ('resurrection-day', 3, 'Christians kept a yearly Pascha, the feast of Christ’s death and resurrection, from the earliest times.', 'supported', 'The churches of Asia traced their custom to the apostle John, and by the 150s Polycarp and Anicetus each defended their church’s practice as inherited from their predecessors [2]. Whether Rome kept any yearly Pascha before about 165 is disputed, and no first-century description survives [2][9].'),
  ('resurrection-day', 4, 'Easter eggs and the Easter bunny come from pagan fertility rites.', 'unverified', 'Eggs and hares are old symbols of new life, but no source ties them to a pre-Christian spring festival. The documented history is later: eggs held back through the Lenten fast [5], and a German folk custom of an egg-bringing hare first recorded in 1682 [8].'),
  ('sunday-worship', 1, 'Constantine changed the Christian day of worship from Saturday to Sunday in 321.', 'contradicted', 'Christian sources from well before 321 describe Sunday gatherings: the Didache, Ignatius around 110 and Justin around 155 [1][2][3]. Constantine’s law made Sunday a civil day of rest; it did not create Christian Sunday worship [6].'),
  ('sunday-worship', 2, 'A pope or church council began Sunday worship.', 'contradicted', 'Sunday gatherings are documented in the first and early second centuries [1][2][3], before any church council met and before any bishop of Rome is recorded ruling on the question. Fourth-century councils such as Laodicea later regulated Sabbath and Sunday practice [7].'),
  ('sunday-worship', 3, 'The Catholic Church changed the Sabbath to Sunday.', 'debated', 'Catholic teaching says Sunday’s observance replaces the Sabbath’s, and older Catholic catechisms say the Church “transferred the solemnity from Saturday to Sunday”; Sabbatarians cite these statements [10][11]. Historically, Sunday gatherings are documented in the first and early second centuries [1][2][3]. The disagreement turns largely on what “the Church” and “changed” mean.'),
  ('sunday-worship', 4, 'Early Christians chose Sunday because of the resurrection.', 'established', 'Justin Martyr gives this reason explicitly, alongside the first day of creation [1], and the Epistle of Barnabas calls Sunday “the eighth day … in which also Jesus rose again from the dead” [5].'),
  ('sunday-worship', 5, 'Sunday worship began in second-century Rome, to set Christians apart from Jews.', 'contradicted', 'Samuele Bacchiocchi argued this in From Sabbath to Sunday (1977) [8]. The earliest witnesses to Sunday gatherings are not Roman: Troas (Acts 20:7), the Didache (probably Syria), Ignatius of Antioch and Pliny in Bithynia [2][3][4]. His thesis is answered in detail in Carson’s volume [9], though what “the Lord’s day” means in Revelation 1:10 remains debated.'),
  ('early-church-leadership', 1, 'Simon Magus went to Rome posing as an apostle and founded a counterfeit Christianity that became the Catholic Church.', 'contradicted', 'Acts shows Simon baptized and then rebuked by Peter (Acts 8:13–24); Justin, Irenaeus and Eusebius treat him as an opponent of the church and the source of heresies, not a leader within it [1][3][4]. No ancient source places him in the leadership of the Roman church or any other, or identifies him with Peter or Rome’s early bishops.'),
  ('early-church-leadership', 2, 'Rome honored Simon Magus as a god with a statue.', 'unverified', 'Justin Martyr reports a statue on the Tiber island inscribed “Simoni Deo Sancto” [3]. In 1574 an inscription beginning “SEMONI SANCO DEO FIDIO,” to the Sabine god Semo Sancus, was found on that island [11], and many historians think Justin misread a dedication of this kind. No other evidence for a statue of Simon survives.'),
  ('early-church-leadership', 3, 'Peter was the first bishop of Rome.', 'debated', 'Irenaeus names Peter and Paul as the founders of the Roman church and Linus as its first bishop [2]; later lists count Peter first. Peter’s presence and death in Rome are widely accepted [4][5], but many historians doubt that Rome had a single bishop in the first century at all [8][9].'),
  ('early-church-leadership', 4, 'Each church was led by a single bishop from the start.', 'contradicted', 'Within single churches, the New Testament and 1 Clement name plural elders or overseers (Philippians 1:1; Acts 20:17, 28) [5], and single bishops appear in Ignatius’s letters around 110 [6]; James’s leadership in Jerusalem is the main early exception [4]. Historians across traditions, Catholic ones included, describe a gradual development [8][9]. Catholic, Orthodox and Anglican teaching holds that the episcopate is nonetheless apostolic, while Reformed and free-church traditions see the single bishop as post-biblical; that disagreement is about the development’s legitimacy, not whether it happened.')
) as v (slug, position, claim, rating, explanation)
join public.traditions t on t.slug = v.slug;

insert into public.tradition_timeline (tradition_id, position, year, label, event)
select t.id, v.position, v.year, v.label, v.event
from (values
  ('halloween', 1, 200, '2nd c. AD', 'A Gaulish calendar, later found at Coligny in France, names a month SAMONIOS.'),
  ('halloween', 2, 609, '609 or 610', 'Pope Boniface IV dedicates the Pantheon in Rome to Mary and all the martyrs.'),
  ('halloween', 3, 835, '835', 'Louis the Pious orders All Saints’ Day kept on November 1 throughout his empire.'),
  ('halloween', 4, 1030, 'early 11th c.', 'Odilo of Cluny orders a yearly commemoration of all the faithful departed, later All Souls’ Day.'),
  ('halloween', 5, 1050, '10th–12th c.', 'Irish monks write down tales that set assemblies and otherworldly events at Samhain.'),
  ('halloween', 6, 1786, '1786', 'Robert Burns publishes “Halloween,” describing Scottish fortune-telling charms.'),
  ('halloween', 7, 1917, '1917', 'The phrase “trick or treat” is first recorded, in Ontario, Canada.'),
  ('christmas', 1, 200, 'c. 200', 'Clement of Alexandria records conflicting calculations of the date of Jesus’ birth.'),
  ('christmas', 2, 274, '274', 'Emperor Aurelian dedicates a temple to the Unconquered Sun in Rome.'),
  ('christmas', 3, 336, '336', 'A Roman list of feasts records December 25 as the birth of Christ.'),
  ('christmas', 4, 354, '354', 'The Chronography of 354 preserves that list beside a civil calendar marking December 25 as the Sun’s birthday.'),
  ('christmas', 5, 386, '386', 'John Chrysostom preaches that Antioch adopted the December 25 feast within the past decade.'),
  ('christmas', 6, 1500, '16th c.', 'Decorated trees for Christmas are first clearly recorded in German-speaking towns.'),
  ('christmas', 7, 1647, '1647', 'England’s Parliament abolishes the observance of Christmas.'),
  ('christmas', 8, 1870, '1870', 'Christmas becomes a federal holiday in the United States.'),
  ('resurrection-day', 1, 54, 'c. 54', 'Paul calls Christ “our passover” (1 Corinthians 5:7).'),
  ('resurrection-day', 2, 155, 'c. 155', 'Polycarp of Smyrna and Anicetus of Rome discuss their churches’ differing customs.'),
  ('resurrection-day', 3, 165, 'c. 165', 'Melito of Sardis preaches On Pascha.'),
  ('resurrection-day', 4, 190, 'c. 190', 'Victor of Rome tries to excommunicate the churches of Asia over the date.'),
  ('resurrection-day', 5, 325, '325', 'The Council of Nicaea agrees on a common Sunday celebration.'),
  ('resurrection-day', 6, 725, '725', 'Bede ties the English name to the month Eosturmonath and a goddess Eostre.'),
  ('resurrection-day', 7, 1682, '1682', 'The egg-bringing Easter hare is first described in Germany.'),
  ('resurrection-day', 8, 1858, '1853–58', 'Alexander Hislop’s The Two Babylons equates Easter with Astarte.'),
  ('sunday-worship', 1, 54, 'c. 54', 'Paul tells the Corinthians to set money aside “upon the first day of the week.”'),
  ('sunday-worship', 2, 95, 'c. 95', 'Revelation refers to “the Lord’s day.”'),
  ('sunday-worship', 3, 100, 'late 1st c.', 'The Didache tells believers to gather every Lord’s day to break bread.'),
  ('sunday-worship', 4, 110, 'c. 110', 'Ignatius of Antioch contrasts keeping the Sabbath with living by the Lord’s Day.'),
  ('sunday-worship', 5, 112, 'c. 112', 'Pliny reports that Christians meet before dawn on a fixed day.'),
  ('sunday-worship', 6, 155, 'c. 155', 'Justin Martyr describes Christian worship “on the day called Sunday.”'),
  ('sunday-worship', 7, 321, '321', 'Constantine makes Sunday a civil day of rest.'),
  ('sunday-worship', 8, 363, 'c. 363', 'The Synod of Laodicea tells Christians to work on the Sabbath and honor the Lord’s day.'),
  ('early-church-leadership', 1, 35, 'c. 35', 'Simon the sorcerer is baptized in Samaria and rebuked by Peter (Acts 8).'),
  ('early-church-leadership', 2, 64, 'c. 64–67', 'Peter and Paul are put to death in Rome, according to early tradition.'),
  ('early-church-leadership', 3, 96, 'c. 96', '1 Clement, from the church in Rome, describes bishops and deacons appointed by the apostles.'),
  ('early-church-leadership', 4, 110, 'c. 110', 'Ignatius’s letters show a single bishop leading each church in Asia Minor.'),
  ('early-church-leadership', 5, 155, 'c. 155', 'Justin Martyr writes that Rome honored Simon Magus with a statue.'),
  ('early-church-leadership', 6, 180, 'c. 180', 'Irenaeus lists Rome’s bishops from Linus and calls Simon the source of heresies.'),
  ('early-church-leadership', 7, 325, 'c. 325', 'Eusebius retells the legend of Peter confronting Simon in Rome.'),
  ('early-church-leadership', 8, 1574, '1574', 'An inscription to the Sabine god Semo Sancus is found on Rome’s Tiber island.')
) as v (slug, position, year, label, event)
join public.traditions t on t.slug = v.slug;

insert into public.tradition_scripture_refs (tradition_id, position, book_id, chapter_start, verse_start, chapter_end, verse_end, note)
select t.id, v.position, b.id, v.cs, v.vs, v.ce, v.ve, v.note
from (values
  ('halloween', 1, 'deuteronomy', 18, 10, 18, 12, 'Forbids divination, sorcery and consulting the dead.'),
  ('halloween', 2, '1-samuel', 28, 7, 28, 19, 'Saul consults a medium at Endor to bring up the dead prophet Samuel.'),
  ('halloween', 3, 'hebrews', 12, 1, 12, 1, 'Speaks of the faithful who have died as “so great a cloud of witnesses.”'),
  ('halloween', 4, 'revelation', 6, 9, 6, 11, 'The souls of martyrs beneath the altar cry out and are given white robes.'),
  ('christmas', 1, 'luke', 2, 1, 2, 20, 'The birth in Bethlehem during a census, with shepherds “abiding in the field” at night. No date is given.'),
  ('christmas', 2, 'matthew', 2, 1, 2, 12, 'Wise men from the east follow a star to the child.'),
  ('christmas', 3, 'jeremiah', 10, 1, 10, 5, 'A tree is cut from the forest, shaped by a craftsman and decked with silver and gold to make an idol.'),
  ('christmas', 4, 'galatians', 4, 4, 4, 4, 'Paul’s direct reference to the birth: God sent forth his Son, “made of a woman.”'),
  ('resurrection-day', 1, 'exodus', 12, 1, 12, 14, 'The first Passover: a lamb killed on the fourteenth day of the first month.'),
  ('resurrection-day', 2, '1-corinthians', 5, 7, 5, 8, '“Christ our passover is sacrificed for us: therefore let us keep the feast.”'),
  ('resurrection-day', 3, 'matthew', 28, 1, 28, 6, 'Women come to the tomb at dawn on the first day of the week and find it empty.'),
  ('resurrection-day', 4, 'acts', 12, 4, 12, 4, 'The only place the KJV says “Easter”; the Greek word is pascha, rendered “passover” elsewhere.'),
  ('sunday-worship', 1, 'exodus', 20, 8, 20, 11, 'The fourth commandment: rest on the seventh day, because God rested after creating.'),
  ('sunday-worship', 2, 'acts', 20, 7, 20, 7, 'Believers at Troas gather “upon the first day of the week” to break bread.'),
  ('sunday-worship', 3, '1-corinthians', 16, 2, 16, 2, 'Paul tells the Corinthians to lay money aside “upon the first day of the week.”'),
  ('sunday-worship', 4, 'revelation', 1, 10, 1, 10, 'John is “in the Spirit on the Lord’s day.”'),
  ('sunday-worship', 5, 'colossians', 2, 16, 2, 17, '“Let no man therefore judge you in meat, or in drink, or in respect of an holyday, or of the new moon, or of the sabbath days.”'),
  ('sunday-worship', 6, 'mark', 2, 27, 2, 28, '“The sabbath was made for man, and not man for the sabbath: therefore the Son of man is Lord also of the sabbath.”'),
  ('early-church-leadership', 1, 'acts', 8, 9, 8, 24, 'Simon the sorcerer is baptized, then offers money for the power to give the Holy Spirit and is rebuked by Peter.'),
  ('early-church-leadership', 2, 'matthew', 16, 17, 16, 19, 'Jesus tells Peter, “upon this rock I will build my church,” and promises him the keys of the kingdom.'),
  ('early-church-leadership', 3, 'acts', 20, 17, 20, 28, 'Paul calls the elders of Ephesus and tells them the Holy Spirit made them overseers.'),
  ('early-church-leadership', 4, 'titus', 1, 5, 1, 7, 'Titus is to ordain elders in every city; Paul goes on, “For a bishop must be blameless.”'),
  ('early-church-leadership', 5, '1-peter', 5, 1, 5, 4, 'Peter addresses the elders as “also an elder.”')
) as v (slug, position, book, cs, vs, ce, ve, note)
join public.traditions t on t.slug = v.slug
join public.books b on b.slug = v.book;

